float nthNorm(vec2 v, float n) {
    return pow(pow(abs(v.x), n) + pow(abs(v.y), n), 1.0/n);
}
float nthNormSDF(vec2 v, float n, float radius) {
    return nthNorm(v, n) - radius;
}
float isMatEigenvec(mat2 M, vec2 v) {
    vec2 u = M*v;
    if (abs(dot(v, u) - length(u) * length(v)) > 50.0) return 0.0;
    return length(u) / length(v);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Tranform the current pixel's coordinate, getting the center to be 0
    vec2 signedCoord = fragCoord - (iResolution.xy / 2.0);
    // M is the inverse of the Matrix we are visualizing (say A = M^(-1))
    mat2 M = mat2(5.0, 0.1, 1.0, 1.5);
    // Plot the eigenvectors of length the sqrt of the corresp. eigenvalue for A*A
    float MtM_eigenval = isMatEigenvec(transpose(M)*M, signedCoord);
    if (MtM_eigenval > 0.0) {
        float AtA_eigenval = 1.0/MtM_eigenval;
        if (length(signedCoord) <= 200.0*sqrt(AtA_eigenval)) {
            fragColor = vec4(0.7, 0.4, 0.2, 1.0);
            return;
        }
    }
    // Plot the eigenvectors of length the sqrt of the corresp. eigenvalue for AA*
    float MMt_eigenval = isMatEigenvec(M*transpose(M), signedCoord);
    if (MMt_eigenval > 0.0) {
        float AAt_eigenval = 1.0/MMt_eigenval;
        if (length(signedCoord) <= 200.0*sqrt(AAt_eigenval)) {
            fragColor = vec4(0.4, 0.2, 0.65, 1.0);
            return;
        }
    }
    // Plot the transformation of ||v||n <= 200 when A is applied to each vector
    float signedDist = nthNormSDF(M * signedCoord / 200.0, iTime/2.0 + 1.0, 1.0);
    vec3 rgbColor = smoothstep(-0.04, 0.00, signedDist) * vec3(1.0);
    fragColor = vec4(rgbColor, 1.0);
}
